// src/services/CommentService.js
import { 
    getFirestore, 
    collection, 
    doc,
    addDoc, 
    updateDoc, 
    getDocs,
    query,
    where,
    orderBy,
    increment,
    serverTimestamp 
  } from 'firebase/firestore';
  import { getDatabase, ref, push } from 'firebase/database';
  
  class CommentService {
    /**
     * Add a comment to a post and update relevant counters
     * - Works for both authenticated and anonymous users
     */
    static async addComment(postId, commentData, user) {
      try {
        if (!postId) {
          throw new Error('Post ID is required');
        }
        
        if (!commentData.content || commentData.content.trim() === '') {
          throw new Error('Comment content cannot be empty');
        }
        
        if (!user) {
          throw new Error('User is required to comment');
        }
        
        console.log('Adding comment to post:', postId);
        console.log('User:', user.uid, 'Anonymous:', user.isAnonymous);
        
        const db = getFirestore();
        const rtdb = getDatabase();
        const commentsCollection = collection(db, 'comments');
        
        // Create comment data
        const comment = {
          postId,
          content: commentData.content.trim(),
          authorId: user.uid,
          // Handle anonymous users properly
          authorName: user.isAnonymous ? 'Anonymous User' : (user.displayName || 'Anonymous'),
          authorPhotoURL: user.photoURL,
          createdAt: serverTimestamp(),
          isAnonymous: user.isAnonymous,
          // Add public read flag to ensure all users can see it
          publicRead: true,
          likes: 0,
          isEdited: false
        };
        
        // Add to Firestore
        const commentRef = await addDoc(commentsCollection, comment);
        console.log('Comment added with ID:', commentRef.id);
        
        // Update comment count on post
        const postRef = doc(db, 'posts', postId);
        await updateDoc(postRef, {
          commentCount: increment(1),
          lastActivity: serverTimestamp()
        });
        console.log('Updated post comment count');
        
        // Add to activity feed in RTDB
        const activitiesRef = ref(rtdb, 'activities');
        await push(activitiesRef, {
          type: 'comment',
          userId: user.uid,
          userName: user.isAnonymous ? 'Anonymous User' : (user.displayName || 'Anonymous'),
          userAvatar: user.photoURL,
          postId: postId,
          commentId: commentRef.id,
          postTitle: commentData.postTitle || 'Untitled Post',
          contentPreview: commentData.content.length > 100 ? 
            commentData.content.substring(0, 100) + '...' : 
            commentData.content,
          timestamp: Date.now(),
          isAnonymous: user.isAnonymous,
          publicRead: true
        });
        console.log('Added to activity feed');
        
        return {
          id: commentRef.id,
          ...comment,
          createdAt: new Date() // Temporary client-side timestamp until the server one syncs
        };
      } catch (error) {
        console.error('Error adding comment:', error);
        throw error;
      }
    }
    
    /**
     * Get comments for a post
     * - Ensures visibility for anonymous users
     */
    static async getCommentsForPost(postId) {
      try {
        if (!postId) {
          throw new Error('Post ID is required');
        }
        
        const db = getFirestore();
        const commentsCollection = collection(db, 'comments');
        
        const commentsQuery = query(
          commentsCollection,
          where('postId', '==', postId),
          // Include publicRead field to ensure anonymous users can see
          where('publicRead', '==', true),
          orderBy('createdAt', 'desc')
        );
        
        const querySnapshot = await getDocs(commentsQuery);
        
        const comments = [];
        querySnapshot.forEach(doc => {
          comments.push({
            id: doc.id,
            ...doc.data()
          });
        });
        
        return comments;
      } catch (error) {
        console.error('Error getting comments:', error);
        return [];
      }
    }
    
    /**
     * Update existing comments to include publicRead flag
     * This is a migration function to fix existing comments
     */
    static async updateExistingComments() {
      try {
        const db = getFirestore();
        const commentsCollection = collection(db, 'comments');
        
        // Find comments without publicRead flag
        const commentsQuery = query(
          commentsCollection,
          where('publicRead', '==', undefined)
        );
        
        const querySnapshot = await getDocs(commentsQuery);
        
        const updatePromises = [];
        querySnapshot.forEach(commentDoc => {
          const commentRef = doc(db, 'comments', commentDoc.id);
          updatePromises.push(
            updateDoc(commentRef, {
              publicRead: true
            })
          );
        });
        
        await Promise.all(updatePromises);
        console.log(`Updated ${updatePromises.length} comments with publicRead flag`);
        
        return updatePromises.length;
      } catch (error) {
        console.error('Error updating existing comments:', error);
        return 0;
      }
    }
  }
  
  export default CommentService;